import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/MyOrders.css";

const MyOrders = () => {
  const userId = sessionStorage.getItem("userId");
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    if (userId) {
      fetch(`${API_BASE_URL}/api/orders/user/${userId}`)
        .then((res) => res.json())
        .then(setOrders)
        .catch((err) => console.error("Failed to load orders", err));
    }
  }, [userId]);

  const cancelOrder = async (orderId) => {
    if (!window.confirm("Are you sure you want to cancel this order?")) return;

    const res = await fetch(`${API_BASE_URL}/api/orders/${orderId}`, {
      method: "DELETE",
    });

    if (res.ok) {
      setOrders(orders.filter((order) => order.id !== orderId));
    } else {
      alert("Failed to cancel order");
    }
  };

  return (
    <div className="orders-wrapper">
      <Navbar />
      <div className="orders-main">
        <h2>📦 My Orders</h2>
        {orders.length === 0 ? (
          <p>No orders placed yet.</p>
        ) : (
          orders.map((order) => (
            <div className="order-card" key={order.id}>
              <div><strong>Order #{order.id}</strong> • {new Date(order.order_date).toLocaleString()}</div>
              <div>Buyer: {order.buyer_name}</div>
              <div>Total: ${order.total}</div>
              <div>
                <strong>Shipping:</strong> {order.shipping_info.address}, {order.shipping_info.city}, {order.shipping_info.state} {order.shipping_info.zip}
              </div>
              <ul>
                {order.items.map((item, i) => (
                  <li key={i}>
                    Listing #{item.listing_id} – ${item.price}
                  </li>
                ))}
              </ul>
              <button className="cancel-btn" onClick={() => cancelOrder(order.id)}>
                Cancel Order
              </button>
            </div>
          ))
        )}
      </div>
      <Footer />
    </div>
  );
};

export default MyOrders;
